contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take a single deposit amount and then call withdrawAll once.
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(true);
        // Ensure this contract has enough Ether to perform the deposit if needed
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount);
        }

        // Perform deposit on c (top-level state-changing call)
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Observe balances before withdraw
        uint cBalBefore = address(c).balance;
        uint myBalBefore = address(this).balance;

        // Attempt withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe balances after withdraw
        uint cBalAfter = address(c).balance;
        uint myBalAfter = address(this).balance;

        // General rule:
        // 1) C's balance cannot decrease by more than the amount we deposited here (others may have funded C before but we only assert about this call's deposit), i.e. cBalBefore - cBalAfter <= depositAmount when subtraction safe.
        //    To avoid underflow in assert, rewrite as: cBalAfter + depositAmount >= cBalBefore
        // 2) If withdrawAll succeeded (did not revert) then this contract's balance did not decrease: myBalAfter >= myBalBefore
        // 3) If withdrawAll reverted then balances remain unchanged with respect to this deposit attempt: cBalAfter == cBalBefore and myBalAfter == myBalBefore
        assert(
            (
                // either it reverted and no balances changed
                (reverted && cBalAfter == cBalBefore && myBalAfter == myBalBefore)
            ) || (
                // or it succeeded: C's balance did not go down by more than depositAmount, and caller's balance did not decrease
                (!reverted && cBalAfter + depositAmount >= cBalBefore && myBalAfter >= myBalBefore)
            )
        );
    }

    // Allow receiving Ether during withdrawAll
    receive() external payable { }
}

