// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount);
        }
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint cBalBefore = address(c).balance;
        uint myBalBefore = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint cBalAfter = address(c).balance;
        uint myBalAfter = address(this).balance;
        assertTrue((
                // either it reverted and no balances changed
                (reverted && cBalAfter == cBalBefore && myBalAfter == myBalBefore)
            ) || (
                // or it succeeded: C's balance did not go down by more than depositAmount, and caller's balance did not decrease
                (!reverted && cBalAfter + depositAmount >= cBalBefore && myBalAfter >= myBalBefore)
            ));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable { }
}
